# Gets the HTML sourcecode using requests and parses it into a bs4 soup object
# Returns the Soup.object
def get_page(url, proxy):
    response = requests.get(url, proxies={"http":proxy, "https:":proxy})
    html = response.text
    soup = BeautifulSoup(html, features="lxml")
    return soup


# Parses the following data from the site: Adress, Price, Kvm, Ejerudgift, Grund kvm, Værelser
# - Liggetid, Opførelses år. Then creates a json-like object and returns it
def parse_page(soup):
    addresses = soup.find_all("div", {"class":"font-black text-sm md:text-base whitespace-nowrap overflow-hidden text-ellipsis mr-2"})
    prices = soup.find_all("span", {"class":"text-blue-900 font-bold text-lg md:text-2xl pr-2"})
    house_info = soup.find_all("span", {"class":"text-gray-800 whitespace-nowrap border-dotted text-sm"})
    urls = soup.find_all("a", {"class":"text-center relative bg-transition-to-l from-white to-red bg-white border border-red rounded text-gray-900 text-sm sm:text-base min-w-full block px-4 sm:px-10 py-2"})

    houses = []
    start, end = 0, 12

    for i in range(int(len(house_info)/12)):

        data_dict = {}
        data_dict["Adresse"] = addresses[i].text
        data_dict["Pris"] = prices[i].text

        info = house_info[start:end]

        data_dict["Kvadratmeter"] = info[0].text
        data_dict["Ejerudgift"] = info[1].text
        data_dict["Grund"] = info[2].text
        data_dict["Værelser"] = info[3].text
        data_dict["Liggetid"] = info[4].text
        data_dict["Opførelses_år"] = info[5].text

        data_dict["Url"] = "https://www.boligsiden.dk/" + urls[i]["href"]

        houses.append(data_dict)

        start = end
        end += 12
        
    return houses



def save_data(data, postnummer):
    
    for item in data:
        if item["Adresse"]:
            address = item["Adresse"]
            price = convert_data(item['Pris'])
            square_footages = convert_data(item['Kvadratmeter'])
            expenses = convert_data(item["Ejerudgift"])
            land = convert_data(item["Grund"])
            rooms = convert_data(item["Værelser"])
            for_sale_days = convert_data(item["Liggetid"])
            construction_year = convert_data(item["Opførelses_år"])
            url = item["Url"]

        postnummer_relation = Postnummer.query.filter_by(postnummer=postnummer).first()


        house = House(
            postnummer_id=postnummer_relation.id,
            address=address,
            price=price,
            square_footages=square_footages,
            expenses=expenses,
            land=land,
            rooms=rooms,
            for_sale_days=for_sale_days,
            construction_year=construction_year,
            url=url
            )

        db.session.add(house)
    db.session.commit()



def convert_data(data):
    try:
        return int(re.sub(r'\D', '', data))
    except ValueError:
        return 0



def extract(postnummer):

    postnummer_id = Postnummer.query.filter_by(postnummer=postnummer).first().id
    for house in House.query.filter_by(postnummer_id=postnummer_id).all():
        db.session.delete(house)
        db.session.commit()
   

    data = []
    proxy = rotate_proxy()
    i = 1


    page_number = i
    url = get_url(postnummer, page_number)
    page = get_page(url, proxy)
    house_data = parse_page(page)
    data.append(house_data)
    


    while house_data:
        page_number = i + 1
        url = get_url(postnummer, page_number)
        page = get_page(url, proxy)
        house_data = parse_page(page)
        data.append(house_data)
        i += 1


    data = [item for sublist in data for item in sublist]
    save_data(data, postnummer)



